// Demo season. One source of truth for both the browser demo and supabase/seed.sql
// (generated by scripts/generate-seed.ts). Handicap indexes are placeholders —
// replace them with each player's current GHIN index before Event 1.
import type { EventFormat, LeagueEvent, MatchType, Player, ResultStatus, SimSettings, Snapshot, Team } from '../lib/types';
import { DEMO_COMMISSIONER, LocalRepo, memoryKV } from './localRepo';

const pid = (n: number) => `00000000-0000-4000-8000-0000000000${String(n).padStart(2, '0')}`;
const eid = (n: number) => `00000000-0000-4000-8000-0000000001${String(n).padStart(2, '0')}`;

export const DEMO_SEASON = 2026;

const tid = (n: number) => `00000000-0000-4000-8000-0000000004${String(n).padStart(2, '0')}`;

