const sim = (green: string, firm: string, wind: string): SimSettings => ({
  green_speed: green,
  fairway_firmness: firm,
  wind,
  putting: 'Full putting, no gimmes',
  mulligans: 'None',
});

const blankSim: SimSettings = { green_speed: '', fairway_firmness: '', wind: '', putting: '', mulligans: '' };

export interface DemoEventSpec {
  n: number;
  name: string;
  format?: EventFormat;
  team_size?: 2 | 4;
  counting_scores?: number;
  match_type?: MatchType;
  hole_si?: number[];
  setup?: Pick<LeagueEvent, 'course_name' | 'tees' | 'par9' | 'course_rating9' | 'slope9' | 'sim_settings'>;
  sessions: { day: 1 | 2; date: string; time: string; players: number[] }[];
  lock?: boolean;
  /** player number → hole scores (or a status for DNF/DNA) */
  scores?: Record<number, { holes: (number | null)[]; status: ResultStatus }>;
  resolveDays?: (1 | 2)[];
  publish?: boolean;
}

