function emptySnapshot(): Snapshot {
  return {
    settings: {
      league_name: 'JIMULATOR Golf Simulator League', season_year: DEMO_SEASON, field_size_basis: 'starters', time_zone: 'America/Chicago',
      match_win_points: null, match_halve_points: null,
    },
    players: demoPlayers.map((p) => ({ ...p })),
    events: demoEvents.map((e) => ({
      id: eid(e.n),
      format: e.format ?? 'individual',
      team_size: e.team_size ?? 2,
      counting_scores: e.counting_scores ?? 1,
      match_type: e.match_type ?? 'singles',
      hole_si: e.hole_si ?? null,
      season_year: DEMO_SEASON,
      event_number: e.n,
      name: e.name,
      course_name: e.setup?.course_name ?? '',
      tees: e.setup?.tees ?? '',
      par9: e.setup?.par9 ?? null,
      course_rating9: e.setup?.course_rating9 ?? null,
      slope9: e.setup?.slope9 ?? null,
      sim_settings: e.setup?.sim_settings ?? { ...blankSim },
      status: 'draft',
      locked_at: null,
      published_at: null,
    })),
    sessions: [],
    assignments: [],
    scores: [],
    results: [],
    teams: demoTeams.map(
      (t): Team => ({ id: tid(t.n), season_year: DEMO_SEASON, name: t.name, player_a: pid(t.a), player_b: pid(t.b) }),
    ),
    entries: [],
    entryMembers: [],
    entryScores: [],
  };
}

export const demoIds = { pid, eid, tid };

/** Plays the demo season through the same rules the app uses. */
export async function buildDemoSnapshot(): Promise<Snapshot> {
  let base = emptySnapshot();
  const kv = memoryKV();
  const repo = new LocalRepo(kv, () => base);
  await repo.signIn(DEMO_COMMISSIONER.email, DEMO_COMMISSIONER.password);
  for (const e of demoEvents) {
    for (const s of e.sessions) await repo.saveSession(eid(e.n), s.day, s.date, s.time);
    let snap = await repo.load();
    for (const s of e.sessions) {
      const session = snap.sessions.find((x) => x.event_id === eid(e.n) && x.session_number === s.day)!;
      for (const p of s.players) await repo.assign(eid(e.n), session.id, pid(p));
    }
    if (e.lock) await repo.lockEvent(eid(e.n));
    snap = await repo.load();
    for (const [p, sc] of Object.entries(e.scores ?? {})) {
      const a = snap.assignments.find((x) => x.event_id === eid(e.n) && x.player_id === pid(Number(p)))!;
      await repo.saveScore(a.id, sc.holes, sc.status);
    }
    for (const d of e.resolveDays ?? []) {
      const session = snap.sessions.find((x) => x.event_id === eid(e.n) && x.session_number === d)!;
      await repo.resolveSession(session.id);
    }
    if (e.publish) await repo.publishEvent(eid(e.n));
  }
  base = await repo.load();
  return base;
}
